Object.defineProperty(Array.prototype, 'last', {
	get: function () { return this[this.length - 1] }
})

class Expression extends Array {
	calc () {
		function __calc__ (Exp) {
			let findMxByPriority = a => a.indexOf(a.reduce((a, b) => b instanceof Action && b.priority > a.priority ? b : a, {priority: 0}));
			let index, res;
			while (Exp.length > 1) {
				index = findMxByPriority(Exp);
				if (!Exp[index].unary) {
					res = Exp[index].use(Exp[index - 1], Exp[index + 1]);
					if (res instanceof VectorMathError)
						return res;
					else
						Exp.splice(index - 1, 3, res);
				}
				else {
					res = Exp[index].use(Exp[index + 1])
					if (res instanceof VectorMathError)
						return res;
					else
						Exp.splice(index, 2, res);
				}
			}
			return Exp[0];
		}

		let arr = this.slice(); // just copy

		let brCount = 0; // not forEach cycle because of error catcher
		for (let i = 0; i < arr.length; i++)
			if (arr[i] instanceof Bracket)
				if (arr[i].open) brCount++;
				else if (!arr[i].open && brCount > 0) brCount--;
				else return new VectorMathError('mathError');

		arr = arr.reduce((a, b) => {
			if (a.last == minus)
				if (b == minus) return a.slice(0, -1).concat(plus);
				else if (b == plus) return a.slice(0, -1).concat(minus);
			else if (a.last == plus)
				if (b == minus) return a.slice(0, -1).concat(minus);
				else if (b == plus) return a.slice(0, -1).concat(plus);
			return a.concat(b);
			}, [] ).reduce((a, b) => {
				if (b == minus && (a.last instanceof Action || a.last == undefined))
					return a.concat(unarMinus);
				else if (b == plus && (a.last instanceof Action || a.last == undefined))
					return a;
				return a.concat(b);
			}, [] );

		arr = arr.map(a => a instanceof Root || a instanceof ComplexDiv || a instanceof Variable || a instanceof Expression ? a.calc() : a)

		if (arr.some(a => a instanceof VectorMathError || a instanceof Vector && a.error))
			return new VectorMathError('Error');

		function rFindBracket (arr, index0) { for (let i = index0 - 1; i >= 0; i--) if (arr[i].open) return i }

		let index, index1, res;
		while ( ~(index = arr.findIndex(a => a instanceof Bracket && !a.open)) ) {
			index1 = rFindBracket(arr, index);
			res = __calc__( arr.slice(index1 + 1, index) );
			if (res instanceof VectorMathError)
				return res;
			else
				arr.splice(index1, index - index1 + 1, res);
		}
		return __calc__(arr);
	}
	includes (obj) {
		return this.some(a => a == obj || (a.includes != undefined ? a.includes(obj) : false));
	}
	static get [Symbol.species] () { return Array }
}

class Num {
	constructor (value=0) { this.value = value }
	calc () {
		if (this.value == 'pi') return Math.PI;
		return Number(this.value)
	}
	add (a) { return new Num( this.calc() + a.calc() ) }
	sub (a) { return new Num( this.calc() - a.calc() ) }
	mul (a) {
		if (a instanceof Vector)
			return Vector({
				vx: [new Num(this.calc() * a.vx.calc())],
				vy: [new Num(this.calc() * a.vy.calc())],
				sx: [a.sx],
				sy: [a.sy],
				newVector: false
			})
		else
			return new Num( this.calc() * a.calc() )
	}
	div (a) {
		if (a.calc() == 0) return new VectorMathError('mathError');
		return new Num( this.calc() / a.calc() )
	}
	pow (a) { return new Num( Math.pow(this.calc(), a.calc()) ) }
	toString () { return this.calc() }
}

class Bracket { constructor (open) { this.open = open }}

class Root {
	constructor (content=[new Num()]) {
		this.content = new Expression(...content);
	}
	calc () {
		let calculatedExp = this.content.calc();
		if (!(calculatedExp instanceof Num))
			return new VectorMathError('typeError')
		if (calculatedExp.calc() < 0)
			throw new VectorMathError('mathError');
		return calculatedExp.pow(new Num(0.5));
	}
	includes (obj) {
		return this.content.includes(obj);
	}
}

class ComplexDiv {
	constructor (tp=new Expression(new Num()), bp=new Expression(new Num())) {
		this.tp = tp;
		this.bp = bp;
	}
	calc () {
		let tpCalced = this.tp.calc(),
			bpCalced = this.bp.calc();
		if (!(bpCalced instanceof Num))
			return new VectorMathError('typeError');
		return tpCalced.div(bpCalced);
	}
	includes (obj) {
		return this.tp.includes(obj) || this.bp.includes(obj);
	}
}

class Action {
	constructor (use, priority, checkFunction, unary=false) {
		this.priority = priority;
		this.use = (a, b) => {
			if (checkFunction(a, b))
				return use(a, b);
			else
				return new VectorMathError('typeError');
		}
		this.unary = unary;
	}
}

class funcAction extends Action {
	constructor (use) {
		super(a => new Num( use( a.calc() ) ), 6, a => a instanceof Num, true);
	}
}


// add functions that checks for possibility of action they checks only types

function checkForNonUnaryAction (a, b) {
	return a instanceof Num && b instanceof Num ||
			a instanceof Vector && b instanceof Vector;
}

let plus = new Action ((a, b) => a.add(b), 3, checkForNonUnaryAction),
	minus = new Action ((a, b) => a.sub(b), 3, checkForNonUnaryAction),
	multip = new Action ((a, b) => a.mul(b), 4, (a, b) => a instanceof Num || b instanceof Num),
	div = new Action ((a, b) => a.div(b), 4, (a, b) => a instanceof Num && b instanceof Num),
	pow = new Action ((a, b) => a.pow(b), 5, (a, b) => a instanceof Num && b instanceof Num),
	dot = new Action ((a, b) => a.scMultip(b), 2, (a, b) => a instanceof Vector && b instanceof Vector),
	sin = new funcAction (Math.sin),
	cos = new funcAction (Math.cos),
	tan = new funcAction (Math.tan),
	unarMinus = new Action (a => a.mul(new Num(-1)), 7, true);

variablesCache = new Map();

class Variable {
	constructor () {
		let Exp = new Expression(...arguments);
		this.event = new MathEvent('variableChange', 'Variable changed', this);
		this.recalc = function () {
			let res = this.recalc0();
			if (res instanceof VectorMathError)
				res.place = this;
			else
				this.event.dispatch();
		}
		this.recalc0 = function () {
			let res = Exp.calc();
			variablesCache.set(this, res);
			return res;
		}
		this.recalc0();
		this.change = function () {
			Exp = new Expression(...arguments);
			this.recalc();
		}
		this.react = function (event) {
			if (Exp.includes(event.place))
				this.recalc();
		}
		this.getFormule = () => Exp;
		// this.link = Symbol();
	}
	calc () { return variablesCache.get(this) }
	add (a) { return new Num( this.calc() + a.calc() ) }
	sub (a) { return new Num( this.calc() - a.calc() ) }
	mul (a) { return new Num( this.calc() * a.calc() ) }
	div (a) { return new Num( this.calc() / a.calc() ) }
	pow (a) { return new Num( Math.pow(this.calc(), a.calc()) ) }
	toString () { return this.calc().toString() } // for debugging
}

events = [];

events.push = function () {
	Array.prototype.push.call(this, ...arguments);
	if (!eventCycleWorking)
		EventCycle();
}

class MathEvent {
	constructor (type, message='Message is not fucking important at the moment', place) {
		this.type = type;
		this.message = message;
		this.place = place;
		this.dispatched = false;
	}
	dispatch () {
		if (!this.dispatched) {
			this.dispatched = true;
			events.push(this);
		}
	}
}

let eventCycleWorking = false;

function EventCycle () {
	eventCycleWorking = true;
	while (events.length != 0) {
		let event = events[0];
		switch (event.type) {
			case 'mathError':
			case 'typeError':
			case 'vectorChange':
				for (let vector of vectors)
					vector.react(event);
			case 'variableChange':
				for (let variable of variablesCache.keys())
					variable.react(event)
				event.dispatched = false;
			default:
				events.shift();
				break;
		}
	}
	eventCycleWorking = false;
}

// make MathError class, that will initiate EventCycle
// make another EventCycle with error checks
// also make storage for whole errors and place, where they been created
// exceptions will raise that will cause ErrorCycle for work
// whole variables with errors in them, or with errors in previous variables must be errored
// their value must equal error

let errorsCache = new Map();

class VectorMathError extends MathEvent {
	get place () {
		return errorsCache.get(this);
	}
	set place (value) {
		if (value != undefined) {
			errorsCache.set(this, value); // placing place in cache
			this.throw();
		}
	}
	throw () {
		this.dispatch();
	}
	destroy () {
		this.place.recalc();
		errorsCache.delete(this);
	}
	toString () { return this.message }
}


let vectors = [];

function Vector ({vx=[new Num()], vy=[new Num()], sx=[new Num()], sy=[new Num()], angle=[new Num()],
	abs=[new Num()], formule=[new Num()], mode='orts', newVector=true}={}) {
	sx = new Variable(...sx);
	sy = new Variable(...sy);
	vx = new Variable(...vx);
	vy = new Variable(...vy);
	abs = new Variable(...abs);
	angle = new Variable(...angle);
	formule = new Expression(...formule);

	let event;
	
	let formuleSymb = Symbol(),
		angleSymb = Symbol();
	let obj = {
		get sx () { return sx.calc() },
		set sx (value) {
			sx.change(...value);
			event.dispatch();
		},
		get sy () { return sy.calc() },
		set sy (value) {
			sy.change(...value);
			event.dispatch();
		},
		get vx () { return vx.calc() },
		set vx (value) {
			vx.change(...value);
			event.dispatch();
		},
		get vy () { return vy.calc() },
		set vy (value) {
			vy.change(...value);
			event.dispatch();
		},
		get abs () { return abs.calc() },
		set abs (value) {
			abs.change(...value);
			event.dispatch();
		},
		get angle () {
			return angle.calc();
		},
		set angle (value) {
			if (value == angleSymb)
				angle.recalc();
			else
				angle.change(...value);
			event.dispatch();
		},
		set mode (value) {
			mode = value;
			switch (value) {
				case 'orts':
					abs.change(new Root([vx, pow, new Num(2), plus, vy, pow, new Num(2)]));
					angle.recalc();
					break;
				case 'abs':
					vx.change(abs, multip, cos, angle);
					vy.change(abs, multip, sin, angle);
					break;
				case 'formule':
					this.formule = formuleSymb; // special value
					break;
			}
		},
		get mode () { return mode },
		set formule (value) {
			if (value != formuleSymb)
				if (value instanceof Expression)
					formule = value;
				else
					formule = new Expression(...value);

			let v = formule.calc();
			if (v instanceof Vector) {
				vx.change(v.vx)
				vy.change(v.vy)
				sx.change(v.sx)
				sy.change(v.sy)
				abs.change(v.abs)
				angle.change(v.angle)
				event.dispatch();
			}
			else if (v instanceof VectorMathError) {
				[vx, vy, sx, sy, abs, angle].forEach(a => {a.change([v])});
				v.place = formule;
			}
		},
		get formule () {
			return formule;
		},
		get absV () { return abs },
		get angleV () { return angle },
		get vxV () { return vx },
		get vyV () { return vy },
		get sxV () { return sx },
		get syV () { return sy },
		react (event) {
			if (event instanceof VectorMathError)
				if ([vx, vy, abs, angle, sx, sy].some(a => a.getFormule().includes(event.place)) ||
					this.mode == 'formule' && formule.includes(event.place)) {
					this.error = true;
					this.formule = formuleSymb;
				}
		},
		rad: true,
		locked: false,
		add (b) {
			return Vector({
				vx: [new Num(this.vx.calc() + b.vx.calc())],
				vy: [new Num(this.vy.calc() + b.vy.calc())],
				sx: [this.sx],
				sy: [this.sy],
				newVector: false
			})
		},
		sub (b) {
			return Vector({
				vx: [new Num(this.vx.calc() - b.vx.calc())],
				vy: [new Num(this.vy.calc() - b.vy.calc())],
				sx: [this.sx],
				sy: [this.sy],
				newVector: false
			})
		},
		mul (n) {
			return Vector({
				vx: [new Num(this.vx.calc() * n.calc())],
				vy: [new Num(this.vy.calc() * n.calc())],
				sx: [this.sx],
				sy: [this.sy],
				newVector: false
			})
		},
		// returns value in radians
		angBetween (a) {
			let a1 = this.angle.calc();
			if (!this.rad)
				a1 = a1 / 180 * Math.PI;
			let a2 = a.angle.calc();
			if (!a.rad)
				a2 = a2 / 180 * Math.PI;
			return a1 - a2;
		},
		scMultip (a) {
			return new Num( this.abs.calc() * a.abs.calc() * Math.cos( this.angBetween(a) ) );
		},
		get error () {
			switch (mode) {
				case 'orts':
					return this.vx instanceof VectorMathError || this.vy instanceof VectorMathError;
				case 'abs':
					return this.abs instanceof VectorMathError || this.angle instanceof VectorMathError;
				case 'formule':
					return this.formule.calc() instanceof VectorMathError;
			}
		}
	}

	event = new MathEvent('vectorChange', 'vectorChange', obj);

	angle.calc = function () {
		if (mode == 'orts') {
			let res;
			try {
				res = Math.atan2(obj.vy.calc(), obj.vx.calc());
			}
			catch (e) {
				return new VectorMathError('typeError');
			}
			return new Num(obj.rad ? res : res * 180 / Math.PI);
		}
		else
			return variablesCache.get(this);
	}

	obj.mode = mode;

	if (newVector)
		vectors.push(obj);

	return obj;
}

Object.defineProperty(Vector, Symbol.hasInstance, {
	value (obj) {
		return obj != undefined && obj.vx != undefined && obj.vy != undefined; // duck check
	}
})

